INSERT INTO public.pages (page_key, page_title, page_slug, content, status, is_visible)
VALUES
('about-village','আমাদের ডালিমগাড়ী','amader-dalimgari',E'ডালিমগাড়ী শুধু একটি নাম নয়—এটি মানুষের বসতি, পারিবারিক স্মৃতি, মাটি, মাঠ, গাছপালা, জলাভূমি ও প্রতিদিনের জীবনযাপনের সমষ্টি। এই ওয়েবসাইটের মূল উদ্দেশ্য হলো গ্রামের পরিচয় ও স্মৃতিকে এমনভাবে সংরক্ষণ করা, যাতে আজকের মানুষ যেমন জানতে পারে, ভবিষ্যৎ প্রজন্মও তেমনি ফিরে তাকাতে পারে।\n\nপ্রকাশ্য সরকারি ওয়েবসূত্রে ডালিমগাড়ী নামটি ১ নং কামদিয়া ইউনিয়নের তথ্যের মধ্যে পাওয়া যায়; সংশ্লিষ্ট ইউনিয়নটি গোবিন্দগঞ্জ, গাইবান্ধার অন্তর্ভুক্ত। এই তথ্যকে ভিত্তি করে গ্রামের পরিচিতি সাজানো হচ্ছে, আর স্থানীয়ভাবে যাচাই করা তথ্য ধাপে ধাপে যুক্ত করা হবে।\n\nএই পাতায় গ্রামের নামের প্রচলিত বানান, অবস্থান, পাড়া-মহল্লা, পরিবার ও জনজীবনের সামগ্রিক পরিচয়, স্থানীয় প্রতিষ্ঠান, গুরুত্বপূর্ণ স্থান এবং গ্রামের সঙ্গে সম্পর্কিত নির্ভরযোগ্য তথ্য সংরক্ষণ করা হবে।', 'published', true),
('history','গ্রামের ইতিহাস','itihash',E'ডালিমগাড়ীর ইতিহাস এখন থেকে ধাপে ধাপে নথিভুক্ত করা হবে। একটি গ্রামের ইতিহাস শুধু প্রতিষ্ঠার সাল দিয়ে শেষ হয় না; মানুষের মুখে মুখে থাকা স্মৃতি, পুরোনো বসতির চিহ্ন, জমি ও পুকুরের পুরোনো নাম, রাস্তা তৈরির সময়, শিক্ষা ও ধর্মীয় প্রতিষ্ঠানের বিকাশ, প্রাকৃতিক পরিবর্তন এবং প্রজন্মের জীবনযাত্রার পরিবর্তন—সবই এর অংশ।\n\nপ্রবীণ বাসিন্দাদের সাক্ষাৎকার, পুরোনো দলিল, ছবি, চিঠি, সরকারি নথি এবং স্থানীয়ভাবে যাচাই করা স্মৃতির ভিত্তিতে এই পাতায় তথ্য যোগ করা হবে। একই ঘটনার একাধিক বর্ণনা থাকলে উৎস ও সময়কাল উল্লেখ করে আলাদা করে রাখা হবে।\n\nআপনার কাছে ডালিমগাড়ীর পুরোনো ছবি, নামের ইতিহাস, উল্লেখযোগ্য ঘটনা বা প্রবীণদের স্মৃতি থাকলে যোগাযোগ পাতার মাধ্যমে জানানো যেতে পারে।', 'published', true),
('nature','প্রকৃতি ও জীববৈচিত্র্য','prokriti',E'ডালিমগাড়ীর প্রাকৃতিক পরিচয়ের মধ্যে মাঠ, গাছপালা, পুকুর, জলাভূমি, দেশি ফুল, পাখি, মাছ, কীটপতঙ্গ এবং অন্যান্য প্রাণবৈচিত্র্যের তথ্য গুরুত্বপূর্ণ। এই পাতা গ্রামের প্রকৃতিকে শুধু দেখানোর জন্য নয়, নথিভুক্ত ও সংরক্ষণ করার জন্য তৈরি।\n\nকোন গাছ কোথায় আছে, কোন মৌসুমে কোন ফুল ফোটে, কোন পাখি কখন দেখা যায়, কোন পুকুরে কী ধরনের মাছ পাওয়া যায়—এ ধরনের স্থানীয় পর্যবেক্ষণ ছবি ও তারিখসহ যুক্ত করা যাবে। এতে সময়ের সঙ্গে গ্রামের পরিবেশ কীভাবে বদলাচ্ছে, সেটিও বোঝা সহজ হবে।\n\nপ্রকৃতি বিষয়ক কোনো তথ্য প্রকাশের আগে স্থানীয়ভাবে যাচাই করা এবং সম্ভব হলে ছবি, স্থান ও সময়ের তথ্য সংযুক্ত করা হবে।', 'published', true),
('agriculture','কৃষি ও ঋতুচক্র','krishi-o-rituchakra',E'গ্রামীণ জীবনের সঙ্গে কৃষি ও ঋতুচক্রের সম্পর্ক খুব গভীর। ডালিমগাড়ীর কৃষিজীবন সম্পর্কে নির্ভরযোগ্য স্থানীয় তথ্য সংরক্ষণের জন্য এই পাতা রাখা হয়েছে।\n\nএখানে মৌসুমভিত্তিক চাষাবাদ, জমির ধরন, স্থানীয়ভাবে ব্যবহৃত বীজ, ফসলের সময়সূচি, সেচ ও পানি ব্যবস্থাপনা, কৃষকের অভিজ্ঞতা, ফসল কাটার সময়ের সামাজিক জীবন এবং কৃষির সঙ্গে যুক্ত পেশাগুলোর তথ্য যুক্ত করা যাবে।\n\nকোন ফসল বাস্তবে এই এলাকায় কতটা চাষ হয়—এ ধরনের তথ্য অনুমান করে নয়, স্থানীয় কৃষক বা নির্ভরযোগ্য নথি থেকে যাচাই করে প্রকাশ করা হবে। ছবি, ভিডিও ও বছরভিত্তিক তথ্য থাকলে ভবিষ্যতে গ্রামের কৃষির পরিবর্তনের একটি মূল্যবান আর্কাইভ তৈরি হবে।', 'published', true),
('people-community','মানুষ ও সামাজিক জীবন','manush-o-samaj',E'একটি গ্রামের সবচেয়ে বড় সম্পদ তার মানুষ। ডালিমগাড়ীর পরিবার, প্রতিবেশী সম্পর্ক, পারস্পরিক সহযোগিতা, সামাজিক আয়োজন, স্থানীয় উদ্যোগ এবং দৈনন্দিন জীবনযাপন এই পাতার মূল বিষয়।\n\nএখানে ব্যক্তিগত গোপনীয়তা রক্ষা করে গ্রামের সামাজিক জীবনের সাধারণ তথ্য, কমিউনিটি উদ্যোগ, স্বেচ্ছাসেবী কাজ, দুর্যোগে পারস্পরিক সহায়তা এবং বিভিন্ন প্রজন্মের অভিজ্ঞতা তুলে ধরা হবে। কোনো ব্যক্তির পরিচয় বা ব্যক্তিগত তথ্য প্রকাশের ক্ষেত্রে অনুমতি ও গোপনীয়তার নিয়ম মানা হবে।\n\nগ্রামের মানুষের গল্পকে সম্মানজনক ও তথ্যভিত্তিকভাবে সংরক্ষণ করাই এই পাতার লক্ষ্য।', 'published', true),
('education','শিক্ষা ও তরুণ প্রজন্ম','shikkha-o-torun-projonmo',E'শিক্ষা একটি গ্রামের দীর্ঘমেয়াদি পরিবর্তনের গুরুত্বপূর্ণ ভিত্তি। ডালিমগাড়ী ও আশপাশের এলাকার শিক্ষা-সম্পর্কিত তথ্য এক জায়গায় সংরক্ষণ করার জন্য এই পাতা তৈরি করা হয়েছে।\n\nস্থানীয় শিক্ষা প্রতিষ্ঠান, শিক্ষার্থীদের সাফল্য, শিক্ষক ও সাবেক শিক্ষার্থীদের স্মৃতি, পাঠাগার বা শিক্ষামূলক উদ্যোগ, অনলাইন শিক্ষার ব্যবহার এবং তরুণদের দক্ষতা উন্নয়নের তথ্য সময়ের সঙ্গে যুক্ত করা যাবে।\n\nপ্রতিষ্ঠানের নাম, ঠিকানা বা সাফল্যের তথ্য প্রকাশের আগে সংশ্লিষ্ট প্রতিষ্ঠান বা নির্ভরযোগ্য উৎস থেকে যাচাই করা হবে।', 'published', true),
('culture-heritage','লোকঐতিহ্য ও সংস্কৃতি','lokoitihyo-o-sanskriti',E'গ্রামের পরিচয় শুধু ভৌগোলিক অবস্থানে নয়; ভাষা, স্থানীয় শব্দ, খাবার, পোশাক, লোকগান, গল্প, খেলাধুলা, উৎসব, পারিবারিক রীতি এবং মানুষের স্মৃতিতেও তার পরিচয় থাকে।\n\nডালিমগাড়ীর স্থানীয় সংস্কৃতি ও ঐতিহ্য নথিভুক্ত করতে এই পাতায় পুরোনো প্রথা, হারিয়ে যেতে বসা শব্দ ও গল্প, স্থানীয় রান্না, মৌসুমি আয়োজন, শিশুদের খেলাধুলা এবং প্রবীণদের স্মৃতি সংরক্ষণ করা যাবে।\n\nকোনো ঐতিহ্যকে গ্রামের নিজস্ব বলে প্রকাশ করার আগে স্থানীয়ভাবে যাচাই করা হবে এবং প্রয়োজনে উৎস বা সাক্ষাৎকারের সময়কাল উল্লেখ করা হবে।', 'published', true),
('water-environment','পুকুর, পানি ও পরিবেশ','pukur-pani-o-poribesh',E'পানি ও পরিবেশ গ্রামের জীবনযাত্রার সঙ্গে সরাসরি যুক্ত। পুকুর, ডোবা, নালা, জলাবদ্ধতা, বৃষ্টির পানি, সেচ এবং গৃহস্থালির পানির ব্যবহার—সবকিছুর সঙ্গে মানুষের জীবন ও প্রকৃতির সম্পর্ক রয়েছে।\n\nএই পাতায় গ্রামের জলাধারগুলোর পরিচয়, ব্যবহার, মৌসুমি পরিবর্তন, মাছ ও জলজ জীববৈচিত্র্য এবং পরিবেশ রক্ষার স্থানীয় উদ্যোগ নথিভুক্ত করা যাবে। কোথায় কী ধরনের জলাধার আছে বা তার আয়তন কত—এ ধরনের নির্দিষ্ট তথ্য যাচাই ছাড়া প্রকাশ করা হবে না।\n\nপরিষ্কার পানি, জলাধার রক্ষা এবং আবর্জনা ব্যবস্থাপনা বিষয়ে স্থানীয় সচেতনতা তৈরির উপযোগী তথ্যও এখানে রাখা যাবে।', 'published', true),
('contact','যোগাযোগ ও তথ্য সংশোধন','jogajog',E'ডালিমগাড়ীর ওয়েবসাইট একটি চলমান কমিউনিটি আর্কাইভ। তাই নতুন তথ্য, পুরোনো ছবি, স্মৃতি, সংশোধন বা স্থানীয় ইতিহাসের উপাদান যুক্ত করার সুযোগ রাখা হয়েছে।\n\nকোনো তথ্য ভুল হলে তার সঠিক তথ্য ও সম্ভব হলে উৎস জানালে তা যাচাই করে সংশোধন করা যাবে। পুরোনো ছবি বা ভিডিও দিলে ছবির আনুমানিক সময়, স্থান এবং পরিচিত ব্যক্তিদের নাম জানা থাকলে সেটিও উল্লেখ করা ভালো।\n\nব্যক্তিগত সংবেদনশীল তথ্য, জাতীয় পরিচয়পত্র নম্বর, ব্যক্তিগত ফোন নম্বর বা অনুমতি ছাড়া ব্যক্তিগত ছবি প্রকাশ করা যাবে না। ওয়েবসাইটের তথ্য ব্যবস্থাপনা ও প্রকাশনার ক্ষেত্রে কমিউনিটির গোপনীয়তা ও সম্মানকে অগ্রাধিকার দেওয়া হবে।', 'published', true)
ON CONFLICT (page_key) DO UPDATE SET page_title=EXCLUDED.page_title,page_slug=EXCLUDED.page_slug,content=EXCLUDED.content,status=EXCLUDED.status,is_visible=EXCLUDED.is_visible,updated_at=now();

UPDATE public.homepage_settings
SET config = config || jsonb_build_object(
  'topicTabs', jsonb_build_object('enabled',true,'items',jsonb_build_array(
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='about-village'),'label','আমাদের ডালিমগাড়ী','enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='nature'),'label','প্রকৃতি','enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='agriculture'),'label','কৃষি','enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='people-community'),'label','মানুষ ও সমাজ','enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='history'),'label','ইতিহাস','enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='culture-heritage'),'label','ঐতিহ্য','enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='education'),'label','শিক্ষা','enabled',true),
    jsonb_build_object('href','#media-gallery','label','ছবি ও ভিডিও','enabled',true)
  )),
  'pageCards', jsonb_build_object('enabled',true,'limit',8,'title','ডালিমগাড়ী সম্পর্কে আরও জানুন','items',jsonb_build_array(
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='about-village'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='history'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='nature'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='agriculture'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='people-community'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='education'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='culture-heritage'),'enabled',true),
    jsonb_build_object('page_id',(select page_id from public.pages where page_key='water-environment'),'enabled',true)
  )),
  'mediaGallery', coalesce(config->'mediaGallery','{}'::jsonb) || jsonb_build_object('showAll',true),
  'posts', coalesce(config->'posts','{}'::jsonb) || jsonb_build_object('enabled',true,'limit',6,'title','গ্রামের খবর')
), updated_at=now()
WHERE settings_id=(select settings_id from public.homepage_settings order by updated_at desc limit 1);

