  jsonb_build_object('label','আমাদের ডালিমগাড়ী','page_id',(select page_id from public.pages where page_key='about-village'),'enabled',true),
  jsonb_build_object('label','ইতিহাস','page_id',(select page_id from public.pages where page_key='history'),'enabled',true),
  jsonb_build_object('label','প্রকৃতি','page_id',(select page_id from public.pages where page_key='nature'),'enabled',true),
  jsonb_build_object('label','কৃষি','page_id',(select page_id from public.pages where page_key='agriculture'),'enabled',true),
  jsonb_build_object('label','মানুষ ও সমাজ','page_id',(select page_id from public.pages where page_key='people-community'),'enabled',true),
  jsonb_build_object('label','শিক্ষা','page_id',(select page_id from public.pages where page_key='education'),'enabled',true),
  jsonb_build_object('label','ঐতিহ্য','page_id',(select page_id from public.pages where page_key='culture-heritage'),'enabled',true),
